import { Badge } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { ConnectorCard } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import { Switch } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
const actions = { display: 'flex', flexWrap: 'wrap', gap: 8 } as const;
function ConnectorCardExample() {
  const [open, setOpen] = useState(false),
    [active, setActive] = useState(true),
    [sync, setSync] = useState(true),
    [draft, setDraft] = useState(true);
  return (
    <>
      <ConnectorCard
        name="File library"
        description="Demo connection, with no access to an external service."
        status={
          <Badge tone={active ? 'success' : 'neutral'}>
            {active ? 'Connected' : 'Disconnected'}
          </Badge>
        }
        meta={active ? `Auto update: ${sync ? 'on' : 'off'}` : 'No service connected'}
        actions={
          <Button
            onClick={() => {
              setDraft(sync);
              setOpen(true);
            }}
          >
            {active ? 'Configure' : 'Connect'}
          </Button>
        }
      />
      <Modal open={open} onClose={() => setOpen(false)} title="Set up integration">
        <form
          style={stack}
          onSubmit={(e) => {
            e.preventDefault();
            setActive(true);
            setSync(draft);
            setOpen(false);
          }}
        >
          <Switch
            label="Auto update"
            checked={draft}
            onChange={(e) => setDraft(e.target.checked)}
          />
          <div style={actions}>
            <Button type="submit" variant="primary">
              Save settings
            </Button>
            {active && (
              <Button
                type="button"
                variant="danger"
                onClick={() => {
                  setActive(false);
                  setOpen(false);
                }}
              >
                Disconnect
              </Button>
            )}
          </div>
        </form>
      </Modal>
    </>
  );
}
export function Example() {
  return <ConnectorCardExample />;
}
